/**
 * Responsive Tabs – Lightweight jQuery Plugin
 * Accordion on mobile, tabs on desktop
 */
(function($) {
    $.fn.responsiveTabs = function(options) {
        var defaults = {
            active: 0,
            collapsible: false
        };
        var settings = $.extend({}, defaults, options);

        return this.each(function() {
            var $container = $(this);
            var $headings = $container.find('> h2');
            var $panels = $container.find('> div');

            if (!$headings.length || !$panels.length) return;

            $container.addClass('r-tabs');

            // Build tab list for desktop
            var $tabList = $('<ul class="r-tabs-nav"></ul>');
            $headings.each(function(i) {
                var text = $(this).text();
                var $tab = $('<li class="r-tabs-tab"><a href="#" data-index="' + i + '">' + text + '</a></li>');
                $tabList.append($tab);
            });
            $container.prepend($tabList);

            // Add classes
            $headings.addClass('r-tabs-accordion-title');
            $panels.addClass('r-tabs-panel');

            function activate(index) {
                $headings.removeClass('r-tabs-state-active');
                $panels.removeClass('r-tabs-state-active').hide();
                $tabList.find('li').removeClass('r-tabs-state-active');

                $headings.eq(index).addClass('r-tabs-state-active');
                $panels.eq(index).addClass('r-tabs-state-active').show();
                $tabList.find('li').eq(index).addClass('r-tabs-state-active');
            }

            // Tab click
            $tabList.on('click', 'a', function(e) {
                e.preventDefault();
                activate($(this).data('index'));
            });

            // Accordion click
            $headings.on('click', function(e) {
                e.preventDefault();
                var index = $headings.index(this);
                if (settings.collapsible && $(this).hasClass('r-tabs-state-active')) {
                    $headings.removeClass('r-tabs-state-active');
                    $panels.hide();
                    $tabList.find('li').removeClass('r-tabs-state-active');
                } else {
                    activate(index);
                }
            });

            // Init
            activate(settings.active);
        });
    };
})(jQuery);
